def amendment_steps(kind,style,cancel=False):
 order=kind+'Order';confirmation=kind+'OrderConfirmation';changed=confirmation+'CancellationInstruction' if cancel else confirmation+' <AmdmntInd> true'
 if style=='direct':return [s('A','B',order),s('B','A',confirmation),s('B','A',changed)]
 if style=='intermediary':return [s('A','M',order),s('M','B',order),s('B','M',confirmation),s('M','A',confirmation),s('B','M',changed),s('M','A',changed)]
 bulk=kind+'BulkOrder';bulkconf=bulk+'Confirmation';bulkchanged=bulkconf+'CancellationInstruction' if cancel else bulkconf+' <AmdmntInd> true'
 return [s('A','M',order),s('C','M',order),s('M','B',bulk),s('B','M',bulkconf),s('M','C',confirmation),s('M','A',confirmation),s('B','M',bulkchanged),s('M','C',changed),s('M','A',changed)]

